"""Generated byte controls only; no authentic source file or OCaml runtime."""
import hashlib
import importlib.util
import json
from pathlib import Path
import struct
import subprocess
import sys
import tempfile
import unittest

HERE = Path(__file__).resolve().parent
SPEC = importlib.util.spec_from_file_location("native_indices", HERE / "native_indices.py")
decoder = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(decoder)


def wrap(payload, n, *, shared=0, words=None, magic=0x8495A6BE):
    words = 3 * n if words is None else words
    return struct.pack(">5I", magic, len(payload), shared, words, words) + payload


def fixture(indices):
    # Test-only canonical byte builder; it does not claim an author-generated file.
    parts = []
    for value in indices:
        code = bytes([0x40 + value]) if value < 64 else (
            b"\x00" + struct.pack(">b", value) if value < 128 else
            b"\x01" + struct.pack(">h", value))
        parts.append(b"\xA0" + code)
    return wrap(b"".join(parts) + b"\x40", len(indices))


def digest(raw):
    return hashlib.sha256(raw).hexdigest()


def inspect(raw, n, companion=None):
    return decoder.inspect_native(raw, source_trial_count=n,
                                  expected_sha256=digest(raw), companion_indices=companion)


class NativeIndices(unittest.TestCase):
    def test_literal_small_byte_example(self):
        # Fixed, independently readable example: list [2;0;2], not a permutation.
        raw = bytes.fromhex("8495a6be00000007000000000000000900000009a042a040a04240")
        out = inspect(raw, 3, [2.0, 0.0, 2.0])
        self.assertEqual(out["native_indices"], [2, 0, 2])
        self.assertEqual(out["count_by_source_id"], [1, 0, 2])
        self.assertEqual(out["omitted_source_ids"], [1])
        self.assertEqual(out["repeated_occurrences"], 1)
        self.assertTrue(out["supplied_companion_equal"])
        self.assertFalse(out["scientific_qualification"])

    def test_integer_encoding_boundaries(self):
        values = [0] * 129
        values[:5] = [63, 64, 127, 128, 0]
        out = inspect(fixture(values), len(values))
        self.assertEqual(out["native_indices"], values)
        self.assertIsNone(out["supplied_companion_equal"])

    def test_maximum_count_preserves_every_occurrence(self):
        values = [9999] * 10000
        self.assertEqual(inspect(fixture(values), 10000)["native_indices"], values)

    def test_disagreement_is_reported_without_repair(self):
        raw = fixture([2, 0, 2])
        out = inspect(raw, 3, [0, 2, 1])
        self.assertEqual(out["native_indices"], [2, 0, 2])
        self.assertEqual(out["mismatch_positions"], [0, 1, 2])
        self.assertFalse(out["supplied_companion_equal"])

    def test_expected_hash_is_required_and_checked(self):
        raw = fixture([0])
        for pin in ("0" * 64, "A" * 64, "", None):
            with self.subTest(pin=pin), self.assertRaises(ValueError):
                decoder.decode_indices(raw, source_trial_count=1, expected_sha256=pin)

    def test_count_domain_is_strict(self):
        for n in (0, -1, 10001, True, 1.0, "1"):
            with self.subTest(n=n), self.assertRaises(ValueError):
                inspect(fixture([0]), n)

    def test_header_fields_and_extent_are_checked(self):
        good = fixture([0])
        variants = [wrap(b"\xA0\x40\x40", 1, shared=1),
                    wrap(b"\xA0\x40\x40", 1, words=4),
                    wrap(b"\xA0\x40\x40", 1, magic=0x8495A6BF),
                    good[:4] + struct.pack(">I", 4) + good[8:],
                    good[:16] + struct.pack(">I", 4) + good[20:]]
        for raw in variants:
            with self.subTest(raw=raw.hex()), self.assertRaises(ValueError):
                inspect(raw, 1)

    def test_rejects_object_and_reference_encodings(self):
        for code in (0x02, 0x03, 0x04, 0x05, 0x06, 0x08, 0x09,
                     0x0B, 0x10, 0x11, 0x12, 0x13, 0x14, 0x18, 0x19, 0xA0):
            raw = wrap(bytes([0xA0, code, 0x40]), 1)
            with self.subTest(code=code), self.assertRaises(ValueError):
                inspect(raw, 1)

    def test_rejects_wrong_block_tags_sizes_and_nested_lists(self):
        for start in (0x80, 0x90, 0xA1, 0xB0, 0x40):
            with self.subTest(start=start), self.assertRaises(ValueError):
                inspect(wrap(bytes([start, 0x40, 0x40]), 1), 1)

    def test_rejects_noncanonical_negative_and_out_of_range_heads(self):
        payloads = [b"\xA0\x00\x00\x40", b"\xA0\x00\xFF\x40",
                    b"\xA0\x01\x00\x40\x40", b"\xA0\x01\x80\x00\x40",
                    b"\xA0\x41\x40"]
        for payload in payloads:
            with self.subTest(payload=payload.hex()), self.assertRaises(ValueError):
                inspect(wrap(payload, 1), 1)

    def test_rejects_truncation_and_trailing_data(self):
        raw = fixture([2, 0, 2])
        for end in range(len(raw)):
            with self.subTest(end=end), self.assertRaises(ValueError):
                inspect(raw[:end], 3)
        for tail in (b"\x40", raw, b"\xA0\x40\x40"):
            with self.subTest(tail=tail.hex()), self.assertRaises(ValueError):
                inspect(raw + tail, 3)
        with self.assertRaises(ValueError):
            inspect(wrap(b"\xA0\x40\x00\x00", 1), 1)

    def test_companion_rejects_missing_nonintegral_and_boolean_values(self):
        raw = fixture([0])
        for values in ([], [True], [0.5], [float("nan")], [float("inf")], [1], [-1], ["0"], (0,)):
            with self.subTest(values=repr(values)), self.assertRaises(ValueError):
                inspect(raw, 1, values)

    def test_cli_reads_only_explicit_files_and_rejects_symlinks(self):
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            native = root / "trial_ids_0"
            companion = root / "companion.json"
            raw = fixture([2, 0, 2])
            native.write_bytes(raw)
            companion.write_text("[2.0,0.0,2.0]")
            command = [sys.executable, "-I", "-S", "-B", str(HERE / "native_indices.py"),
                       "--native", str(native), "--source-trial-count", "3",
                       "--expected-sha256", digest(raw), "--companion-json", str(companion)]
            process = subprocess.run(command, capture_output=True, timeout=5)
            self.assertEqual(process.returncode, 0, process.stderr.decode())
            self.assertEqual(json.loads(process.stdout)["native_indices"], [2, 0, 2])
            native.unlink()
            native.symlink_to(companion)
            process = subprocess.run(command, capture_output=True, timeout=5)
            self.assertEqual(process.returncode, 2)
            self.assertEqual(process.stdout, b"")

    def test_reader_rejects_oversize_and_nonfinite_companion_json(self):
        with tempfile.TemporaryDirectory() as td:
            path = Path(td) / "oversized"
            path.write_bytes(b"12345")
            with self.assertRaises(ValueError):
                decoder.read_regular(path, 4)
        with self.assertRaises(ValueError):
            decoder.parse_companion(b"[NaN]")

    def test_explicit_null_companion_is_not_treated_as_omitted(self):
        for raw_json in (b"null", b"true", b"0", b"{}"):
            with self.subTest(raw_json=raw_json), self.assertRaises(ValueError):
                decoder.parse_companion(raw_json)
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            native = root / "trial_ids_0"
            companion = root / "companion.json"
            raw = fixture([0])
            native.write_bytes(raw)
            companion.write_text("null")
            command = [sys.executable, "-I", "-S", "-B", str(HERE / "native_indices.py"),
                       "--native", str(native), "--source-trial-count", "1",
                       "--expected-sha256", digest(raw)]
            omitted = subprocess.run(command, capture_output=True, timeout=5)
            self.assertEqual(omitted.returncode, 0, omitted.stderr.decode())
            self.assertIsNone(json.loads(omitted.stdout)["supplied_companion_equal"])
            supplied = subprocess.run(command + ["--companion-json", str(companion)],
                                      capture_output=True, timeout=5)
            self.assertEqual(supplied.returncode, 2)
            self.assertEqual(supplied.stdout, b"")
            self.assertIn(b"must contain a list", supplied.stderr)


if __name__ == "__main__":
    unittest.main(verbosity=1)
